{
  "contract": "WuZeTian",
  "closure": {
    "site_function": "addLiquidity",
    "site_call": ".call",
    "functions": ["addLiquidity", "burn", "transfer", "transferFrom"],
    "justification": "These functions manipulate _balances, which is exposed during the risky call in addLiquidity. The closure must account for all functions that can affect the exposed state variables."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": ["burn", "transfer", "transferFrom"],
    "nesting_bound": {"addLiquidity": 0}
  },
  "phases": {
    "function": "addLiquidity",
    "pre": {"name": "pre", "from_marker": "entry", "to_marker": "before_call"},
    "exposed": {"name": "exposed", "from_marker": "before_call", "to_marker": "after_call"},
    "post": {"name": "post", "from_marker": "after_call", "to_marker": "exit"},
    "linearization_point": "after_call"
  },
  "ghost_state": [
    {"name": "inFlight", "sol_type": "uint256", "meaning": "tracks the in-flight token balance during callback", "backed_by_storage": false}
  ],
  "exposure_invariant": {
    "formula": "_sum__balances + _swapLimit == _totalSupply + inFlight",
    "stable_formula": "_sum__balances + _swapLimit == _totalSupply",
    "kind": "conserve"
  },
  "composition": {
    "target_property": "_sum__balances + _swapLimit == _totalSupply",
    "rule": "The exposure invariant ensures conservation of total supply including in-flight balances during reentrant callbacks."
  }
}
